for k, (lp, hp, lr, hr) in POL.items():
    a = A[k]
    a['lo_pole'], a['hi_pole'], a['lo_reading'], a['hi_reading'] = lp, hp, lr, hr
    # 名詞句は「軸名（方向）」に統一する。「控えめさ」「低さ」で低得点側を弱さのように読ませない
    a['hi_noun'] = '<b>%s</b>（%s）' % (a['name'], hp)
    a['lo_noun'] = '<b>%s</b>（%s）' % (a['name'], lp)
    assert '控えめ' not in lr + hr and '弱' not in lr + hr

